-- Points, quests and the shop, owned by the server. Run after 006. Safe to run again.
-- Then run 008_economy_catalog.sql (the quest and shop catalogues, generated by
-- `npm run gen:economy` in frontend/).
--
-- Before this file, points lived inside migo_profiles.record->rewards and the browser saved them
-- whole, so anyone could give themselves points. Now:
--   * Every points change is one row in `points_ledger`, unique per (profile, ref):
--       'quest:<assignment id>'  a claimed quest            'purchase:<item id>'  a shop purchase
--       'legacy:<old refId>'     imported from the old record (see economy_import_legacy)
--     so a reward or a purchase can never apply twice (double clicks, two tabs, retries).
--   * The browser only sends ids. Rewards come from `quest_defs`, prices from `shop_items` (both
--     seeded by 008). Quest progress is computed here from stored data (hunts, photos, the saved
--     profile, page visits, purchases), never self-reported.
--   * The balance (sum of the ledger) can never go below zero: purchases check it, and a trigger
--     refuses any insert that would leave a profile negative.
--   * Days and weeks are computed here from the server clock in the person's saved timezone
--     (profiles.timezone). The device clock is never used.
--   * migo_save_record no longer trusts record.rewards: it replaces it with a read-only mirror built
--     from these tables, so old app versions still show the right numbers but can't add points.
--   * Every function takes p_profile_id and applies the owner rule from 005 (migo_assert_owner):
--     a profile with a login only works with that login; device accounts without a login
--     (auth_user_id null) work as before. Every write first locks the profile row
--     (select ... for update), so two requests for the same person run one after the other.
--
-- Periods (same keys as features/quests/engine.ts):
--   weekly     period_key 'w:2026-W48', slot 1        ISO week, Monday 00:00 to next Monday 00:00
--   adventure  period_key 'a:2026-W48', slots 1..3    same week
--   daily      period_key 'd:2026-11-23', slots 1..3  calendar day, 00:00 to 00:00
--   starter    period_key 'starter', no slot          never expires, one per starter quest
-- The API's periodKey adds the slot for dailies and adventures ('d:2026-11-23:2', 'a:2026-W48:1').
--
-- Timezones can't be used to farm quests:
--   * A (profile, period, slot) is issued at most once, ever: once any row exists for it (active,
--     completed, expired or replaced), it is never issued again.
--   * Periods only move forward: the current day (or week) is the later of "today in the saved
--     timezone" and the latest one already issued. Moving west (back into "yesterday") keeps the
--     day already issued instead of issuing yesterday; moving east can only start the next day a
--     few hours early, and the timezone can change at most once every 20 hours.
--   * On a timezone change, the active quests' windows (starts_at/expires_at) are recomputed for the
--     new timezone, so "expires at midnight" always means midnight where the person is now.
--
-- Testing: economy_now() is the clock every function uses. It returns now() unless the setting
-- `economy.test_now` is set in the session (`set local economy.test_now = '2026-11-23 10:00Z'`),
-- which only backend/tests/economy_test.sql does. Browsers can't set it: PostgREST only sets its
-- own request.* settings (headers and JWT claims go into request.headers / request.jwt.claims), and
-- the API roles can't run SQL. As a second lock, the setting is ignored for PostgREST connections
-- (session_user = 'authenticator', the role PostgREST logs in as on Supabase).

-- ---------------------------------------------------------------------------
-- Clock and small helpers
-- ---------------------------------------------------------------------------

create or replace function economy_now() returns timestamptz
language plpgsql stable set search_path = public as $$
declare
  t text := nullif(current_setting('economy.test_now', true), '');
begin
  if t is null or session_user::text in ('authenticator', 'anon', 'authenticated') then
    return now();
  end if;
  return t::timestamptz;
end;
$$;

-- A JSON array of strings as text[] ('{}' for anything else).
create or replace function economy_text_array(j jsonb) returns text[]
language sql immutable as $$
  select case when jsonb_typeof(j) = 'array'
              then coalesce(array(select x from jsonb_array_elements(j) e(x0), lateral (select e.x0 #>> '{}' as x) s
                                   where jsonb_typeof(e.x0) = 'string'), '{}')
              else '{}'::text[] end
$$;

-- Milliseconds since epoch (as the app stores them) to a timestamp; null if it isn't a sane number.
create or replace function economy_ms(j jsonb) returns timestamptz
language sql immutable as $$
  select case when jsonb_typeof(j) = 'number' and (j #>> '{}')::numeric between 0 and 100000000000000
              then to_timestamp((j #>> '{}')::double precision / 1000) end
$$;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

alter table profiles add column if not exists timezone text not null default 'UTC';
alter table profiles add column if not exists timezone_changed_at timestamptz;

create table if not exists quest_defs (
  id           text primary key check (char_length(id) between 1 and 100),
  category     text not null check (category in ('weekly', 'daily', 'adventure', 'starter')),
  title        text not null,
  description  text not null default '',
  objective    text not null default '',
  reward       integer not null check (reward > 0),
  -- QuestCondition from features/economy/types.ts, e.g. {"type":"photos","count":3,"distinctCities":3}
  condition    jsonb not null check (jsonb_typeof(condition) = 'object' and condition ? 'type'),
  interests    text[] not null default '{}',
  company      text check (company in ('solo', 'companion', 'either')),
  modes        text[] not null default '{}',
  avoid_for    text[] not null default '{}',
  effort       text check (effort in ('light', 'moderate', 'big')),
  retired      boolean not null default false,
  updated_at   timestamptz not null default now()
);

create table if not exists shop_items (
  id              text primary key check (char_length(id) between 1 and 100),
  kind            text not null check (kind in ('accessory', 'backdrop')),
  name            text not null default '',
  slot            text not null check (slot in ('head', 'hair', 'face', 'ears', 'neck', 'back', 'hand', 'backdrop')),
  -- Rarity for accessories (common/uncommon/rare/premium), tier for backdrops (standard/detailed/premium).
  rarity_or_tier  text not null,
  price           integer not null check (price > 0),
  retired         boolean not null default false,
  updated_at      timestamptz not null default now()
);

create table if not exists points_ledger (
  id          uuid primary key default gen_random_uuid(),
  profile_id  uuid not null references profiles(id) on delete cascade,
  amount      integer not null check (amount <> 0),
  kind        text not null check (kind in ('quest', 'purchase', 'legacy', 'adjustment')),
  ref         text not null check (char_length(ref) between 1 and 220),
  label       text not null default '' check (char_length(label) <= 200),
  created_at  timestamptz not null default now(),
  unique (profile_id, ref)
);
create index if not exists points_ledger_profile_idx on points_ledger (profile_id, created_at desc);

-- Owned items. item_id is deliberately not a foreign key: an item id saved in an account stays
-- valid even if the catalogue is edited (ids are never deleted, only retired).
create table if not exists inventory (
  profile_id   uuid not null references profiles(id) on delete cascade,
  item_id      text not null check (char_length(item_id) between 1 and 100),
  price_paid   integer not null default 0 check (price_paid >= 0),
  acquired_at  timestamptz not null default now(),
  primary key (profile_id, item_id)
);

-- What the avatar wears: one item per slot, and only items the person owns.
create table if not exists equipped (
  profile_id  uuid not null references profiles(id) on delete cascade,
  slot        text not null check (slot in ('head', 'hair', 'face', 'ears', 'neck', 'back', 'hand', 'backdrop')),
  item_id     text not null,
  primary key (profile_id, slot),
  foreign key (profile_id, item_id) references inventory (profile_id, item_id) on delete cascade
);

create table if not exists quest_assignments (
  id            uuid primary key default gen_random_uuid(),
  profile_id    uuid not null references profiles(id) on delete cascade,
  def_id        text not null references quest_defs(id),
  category      text not null check (category in ('weekly', 'daily', 'adventure', 'starter')),
  period_key    text not null,
  slot          integer check (slot between 1 and 3),
  status        text not null default 'active' check (status in ('active', 'completed', 'expired', 'replaced')),
  assigned_at   timestamptz not null default now(),
  -- The window progress is counted in: [starts_at, expires_at). Both null for starter quests.
  starts_at     timestamptz,
  expires_at    timestamptz,
  completed_at  timestamptz,
  ledger_id     uuid references points_ledger(id) on delete set null,
  check ((category = 'starter') = (slot is null))
);
-- One live quest per period and slot (a refreshed daily leaves a 'replaced' row behind).
create unique index if not exists quest_assignments_live_slot
  on quest_assignments (profile_id, period_key, slot)
  where status in ('active', 'completed') and slot is not null;
create unique index if not exists quest_assignments_starter_once
  on quest_assignments (profile_id, def_id) where category = 'starter';
create index if not exists quest_assignments_profile_idx on quest_assignments (profile_id, category, period_key);

-- One row per profile per day the daily refresh was used: the primary key is the "once a day" rule.
create table if not exists daily_refreshes (
  profile_id  uuid not null references profiles(id) on delete cascade,
  period_key  text not null,
  used_at     timestamptz not null default now(),
  primary key (profile_id, period_key)
);

-- Sections of the app the person has opened (recorded by the app). first_at never changes;
-- last_at moves forward, so daily "open the map" quests can be checked too.
create table if not exists app_visits (
  profile_id  uuid not null references profiles(id) on delete cascade,
  page        text not null check (page in ('map', 'shop', 'gallery', 'chat', 'quests')),
  first_at    timestamptz not null default now(),
  last_at     timestamptz not null default now(),
  primary key (profile_id, page)
);
alter table app_visits add column if not exists last_at timestamptz not null default now();

-- When the server first saw each city (by placeId) in the person's "Where have you explored?" list.
-- addedAt inside the record is written by the browser, so a "new city this week" also needs the
-- server to have first seen it this week (removing and re-adding a city doesn't make it new).
create table if not exists seen_cities (
  profile_id     uuid not null references profiles(id) on delete cascade,
  place_id       text not null,
  first_seen_at  timestamptz not null default now(),
  primary key (profile_id, place_id)
);

-- Profiles whose old record.rewards has been carried over (once each; see economy_import_legacy).
create table if not exists legacy_imports (
  profile_id      uuid primary key references profiles(id) on delete cascade,
  imported_at     timestamptz not null default now(),
  legacy_balance  integer not null default 0
);

alter table quest_defs        enable row level security;
alter table shop_items        enable row level security;
alter table points_ledger     enable row level security;
alter table inventory         enable row level security;
alter table equipped          enable row level security;
alter table quest_assignments enable row level security;
alter table daily_refreshes   enable row level security;
alter table app_visits        enable row level security;
alter table seen_cities       enable row level security;
alter table legacy_imports    enable row level security;
-- No policies and no grants: only the functions below can read or write these tables.
revoke all on quest_defs, shop_items, points_ledger, inventory, equipped, quest_assignments,
              daily_refreshes, app_visits, seen_cities, legacy_imports
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Ledger rules: never negative, never rewritten
-- ---------------------------------------------------------------------------

create or replace function economy_ledger_not_negative() returns trigger
language plpgsql set search_path = public as $$
begin
  if exists (select 1
               from (select distinct profile_id from new_rows) n
              where (select coalesce(sum(l.amount), 0) from points_ledger l where l.profile_id = n.profile_id) < 0) then
    raise exception 'Not enough points' using errcode = '23514', hint = 'insufficient_points';
  end if;
  return null;
end;
$$;

-- Statement-level, so a batch (like the legacy import) is checked once at the end.
drop trigger if exists points_ledger_not_negative on points_ledger;
create trigger points_ledger_not_negative
  after insert on points_ledger
  referencing new table as new_rows
  for each statement execute function economy_ledger_not_negative();

create or replace function economy_ledger_immutable() returns trigger
language plpgsql set search_path = public as $$
begin
  raise exception 'Ledger rows can''t be changed; add an adjustment row instead' using errcode = '42501';
end;
$$;

drop trigger if exists points_ledger_immutable on points_ledger;
create trigger points_ledger_immutable
  before update on points_ledger
  for each row execute function economy_ledger_immutable();

-- ---------------------------------------------------------------------------
-- Internal helpers (not callable by the browser)
-- ---------------------------------------------------------------------------

-- Owner check + per-profile lock. Every write starts with this.
create or replace function economy_lock(p_profile_id uuid) returns profiles
language plpgsql security definer set search_path = public as $$
declare
  p profiles;
begin
  perform migo_assert_owner(p_profile_id);
  select * into p from profiles where id = p_profile_id for update;
  if not found then
    raise exception 'Unknown profile %', p_profile_id using errcode = 'P0002';
  end if;
  return p;
end;
$$;

create or replace function economy_record(p_profile_id uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce((select record from migo_profiles where profile_id = p_profile_id), '{}'::jsonb)
$$;

-- The tourist's active trip from the record (null if none).
create or replace function economy_active_trip(p_rec jsonb) returns jsonb
language sql immutable as $$
  select t
    from jsonb_array_elements(case when jsonb_typeof(p_rec #> '{tourist,trips}') = 'array'
                                   then p_rec #> '{tourist,trips}' else '[]'::jsonb end) t
   where jsonb_typeof(t) = 'object' and t ->> 'id' = p_rec #>> '{tourist,activeTripId}'
   limit 1
$$;

-- [starts_at, ends_at) of a period key in a timezone. Nulls for 'starter' or an unknown key.
create or replace function economy_period_bounds(p_key text, p_tz text,
                                                 out starts_at timestamptz, out ends_at timestamptz)
language plpgsql stable set search_path = public as $$
declare
  d date;
begin
  if p_key ~ '^d:\d{4}-\d{2}-\d{2}$' then
    d := substr(p_key, 3)::date;
    starts_at := d::timestamp at time zone p_tz;
    ends_at := (d + 1)::timestamp at time zone p_tz;
  elsif p_key ~ '^[wa]:\d{4}-W\d{2}$' then
    d := to_date(substr(p_key, 3), 'IYYY-"W"IW');   -- the Monday of that ISO week
    starts_at := d::timestamp at time zone p_tz;
    ends_at := (d + 7)::timestamp at time zone p_tz;
  end if;
end;
$$;

-- The number a quest counts to. Same as conditionTarget() in features/quests/catalog/index.ts.
create or replace function economy_target(p_cond jsonb) returns integer
language sql immutable as $$
  select case
    when p_cond ->> 'type' in ('profile', 'visit') then 1
    when p_cond ->> 'type' = 'photos'
      then greatest(1, coalesce((p_cond ->> 'count')::int, 1), coalesce((p_cond ->> 'distinctCities')::int, 0))
    else greatest(1, coalesce((p_cond ->> 'count')::int, 1))
  end
$$;

-- Has the person finished a hunt with a teammate (team of two)? Companion-only weeklies need it.
create or replace function economy_has_teamed_up(p_profile_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1
      from team_members tm
      join submissions s on s.team_id = tm.team_id
     where tm.profile_id = p_profile_id
       and (select count(*) from team_members x where x.team_id = tm.team_id) >= 2)
$$;

-- Raw progress of one condition, from stored data only, counting what happened in [p_from, p_to)
-- (null bounds = all time, for starter quests). Same rules as rawProgress() in
-- features/quests/engine.ts. p_self = the assignment itself (not counted by quests_completed).
create or replace function economy_progress(p_profile_id uuid, p_rec jsonb, p_cond jsonb,
                                            p_from timestamptz, p_to timestamptz, p_self uuid default null)
returns integer
language plpgsql stable security definer set search_path = public as $$
declare
  v_type   text := p_cond ->> 'type';
  v_from   timestamptz := coalesce(p_from, '-infinity'::timestamptz);
  v_to     timestamptz := coalesce(p_to, 'infinity'::timestamptz);
  v_count  integer := coalesce((p_cond ->> 'count')::int, 1);
  v_dc     integer := coalesce((p_cond ->> 'distinctCities')::int, 0);
  v_kinds  text[] := economy_text_array(p_cond -> 'huntKinds');
  v_cats   text[] := economy_text_array(p_cond -> 'categories');
  v_n      integer := 0;
  v_cities integer := 0;
  v_part   integer;
  v_trip   jsonb;
  v_local  jsonb;
begin
  if v_type = 'hunts' then
    select case when coalesce((p_cond ->> 'distinctHunts')::boolean, false)
                then count(distinct s.hunt_id) else count(*) end
      into v_n
      from submissions s
      join team_members tm on tm.team_id = s.team_id and tm.profile_id = p_profile_id
      join hunts h on h.id = s.hunt_id
     where s.created_at >= v_from and s.created_at < v_to
       and (not coalesce((p_cond ->> 'withPartner')::boolean, false)
            or (select count(*) from team_members x where x.team_id = s.team_id) >= 2)
       and (cardinality(v_kinds) = 0 or h.kind = any (v_kinds));
    return v_n;

  elsif v_type = 'photos' then
    -- Upload time (created_at, set by the server), not the photo's own "taken at".
    select count(*),
           count(distinct coalesce(p.place_id, lower(btrim(p.city_name)))) filter (where coalesce(btrim(p.city_name), '') <> '')
      into v_n, v_cities
      from photos p
     where p.profile_id = p_profile_id
       and p.created_at >= v_from and p.created_at < v_to
       and (not (coalesce((p_cond ->> 'requireCity')::boolean, false) or v_dc > 0)
            or coalesce(btrim(p.city_name), '') <> '');
    if v_dc <= 0 then
      return v_n;
    end if;
    -- The first photo from each city counts (up to distinctCities), then further photos fill the
    -- rest of `count`.
    v_part := least(v_cities, v_dc);
    return v_part + least(v_n - v_part, greatest(0, v_count - v_dc));

  elsif v_type = 'new_cities' then
    -- Pinned cities (with a placeId) still in the list now, added in the period by the record's
    -- addedAt AND first seen by the server in the period.
    select count(distinct c ->> 'placeId')
      into v_n
      from jsonb_array_elements(case when jsonb_typeof(p_rec #> '{universal,citiesDiscovered}') = 'array'
                                     then p_rec #> '{universal,citiesDiscovered}' else '[]'::jsonb end) c
      join seen_cities sc on sc.profile_id = p_profile_id and sc.place_id = c ->> 'placeId'
     where jsonb_typeof(c) = 'object'
       and nullif(btrim(c ->> 'placeId'), '') is not null
       and economy_ms(c -> 'addedAt') >= v_from and economy_ms(c -> 'addedAt') < v_to
       and sc.first_seen_at >= v_from and sc.first_seen_at < v_to;
    return v_n;

  elsif v_type = 'profile' then
    case p_cond ->> 'check'
      when 'questionnaire_complete' then
        return (jsonb_typeof(p_rec -> 'universal') = 'object'
                and jsonb_typeof(p_rec -> 'universalCompletedAt') = 'number'
                and coalesce(btrim(p_rec #>> '{universal,homeCity}'), '') <> '')::int;
      when 'home_city_pinned' then
        return (coalesce(nullif(btrim(p_rec #>> '{universal,homeCityPlace,placeId}'), ''),
                         nullif(btrim(p_rec #>> '{local,homeCityPlace,placeId}'), '')) is not null)::int;
      when 'avatar_chosen' then
        -- An avatar id from lib/avatars.ts (old emoji avatars don't count).
        return coalesce((select avatar ~ '^[a-z0-9]+(-[a-z0-9]+)*$' from profiles where id = p_profile_id), false)::int;
      when 'first_city' then
        return (jsonb_typeof(p_rec #> '{universal,citiesDiscovered}') = 'array'
                and jsonb_array_length(p_rec #> '{universal,citiesDiscovered}') > 0)::int;
      when 'both_modes_ready' then
        -- Same as isModeReady() for both modes (features/profile/model.ts).
        v_trip := economy_active_trip(p_rec);
        v_local := p_rec -> 'local';
        return (
          v_trip is not null
          and coalesce(btrim(v_trip ->> 'destination'), '') <> ''
          and v_trip ->> 'companions' is not null
          and v_trip #>> '{budget,level}' is not null
          and case v_trip #>> '{dates,kind}'
                when 'approx' then coalesce(btrim(v_trip #>> '{dates,approx}'), '') <> ''
                when 'dates' then coalesce(v_trip #>> '{dates,start}', '') <> ''
                else false end
          and jsonb_typeof(v_local) = 'object'
          and coalesce(btrim(v_local ->> 'homeCity'), '') <> ''
          and cardinality(economy_text_array(v_local -> 'languages')) > 0
          and cardinality(economy_text_array(v_local -> 'activities')) > 0
          and cardinality(economy_text_array(v_local -> 'availability')) > 0
          and v_local ->> 'duration' is not null)::int;
      else
        return 0;
    end case;

  elsif v_type = 'visit' then
    return exists (select 1 from app_visits v
                    where v.profile_id = p_profile_id and v.page = p_cond ->> 'page'
                      and v.last_at >= v_from and v.first_at < v_to)::int;

  elsif v_type = 'quests_completed' then
    select count(*) into v_n
      from quest_assignments a
     where a.profile_id = p_profile_id and a.status = 'completed'
       and a.id is distinct from p_self
       and a.completed_at >= v_from and a.completed_at < v_to
       and (cardinality(v_cats) = 0 or a.category = any (v_cats));
    return v_n;

  elsif v_type = 'purchases' then
    select count(*) into v_n from inventory i
     where i.profile_id = p_profile_id and i.acquired_at >= v_from and i.acquired_at < v_to;
    return v_n;

  elsif v_type = 'equipped' then
    select count(*) into v_n from equipped e where e.profile_id = p_profile_id;
    return v_n;
  end if;
  return 0;
end;
$$;

-- The old challenge system's ref for the same quest and period ('legacy:challenge:<id>:<period>'),
-- so a reward claimed before this migration isn't paid again. Null when there's no equivalent.
create or replace function economy_legacy_ref(p_def_id text, p_category text, p_period_key text) returns text
language sql immutable as $$
  select 'legacy:challenge:' || p_def_id || ':' || case
    when p_category = 'starter' then 'once'
    when p_category = 'daily' then substr(p_period_key, 3)
    when p_category = 'weekly' then 'week-of-' || to_char(to_date(substr(p_period_key, 3), 'IYYY-"W"IW'), 'YYYY-MM-DD')
  end
$$;

-- Stores one assignment (already claimed under the old system -> stored as completed).
create or replace function economy_assign(p_profile_id uuid, p_def_id text, p_category text, p_period_key text,
                                          p_slot integer, p_starts timestamptz, p_ends timestamptz)
returns void
language plpgsql security definer set search_path = public as $$
declare
  old points_ledger;
begin
  select * into old from points_ledger
   where profile_id = p_profile_id and ref = economy_legacy_ref(p_def_id, p_category, p_period_key);
  insert into quest_assignments (profile_id, def_id, category, period_key, slot, status, assigned_at,
                                 starts_at, expires_at, completed_at, ledger_id)
  values (p_profile_id, p_def_id, p_category, p_period_key, p_slot,
          case when old.id is null then 'active' else 'completed' end,
          economy_now(), p_starts, p_ends, old.created_at, old.id)
  on conflict do nothing;
end;
$$;

-- Picks up to p_n quests of a category for one period.
--   p_exclude   never pick (already in this period, or the one being replaced)
--   p_recent    avoid if possible (shown recently)
--   p_existing  the period's other live quests (for the companion rule)
-- Hard rules: not retired; suits the active mode (def.modes); never one whose avoid_for matches the
-- person's accessibility needs (universal + active trip + local, if present).
-- Companion-only quests: at most one per period, never the only option (a lone daily/adventure
-- companion pick is dropped), and a companion-only weekly only for someone who has teamed up before.
-- Adventures are personalised: most shared interests first (with the universal interests, plus the
-- trip's in Tourist mode), then effort matching the pace (relaxed→light, balanced→moderate,
-- fast→big), then random. Dailies and weeklies are random.
create or replace function economy_pick(p_profile_id uuid, p_rec jsonb, p_category text, p_n integer,
                                        p_exclude text[], p_recent text[], p_existing text[])
returns text[]
language plpgsql security definer set search_path = public as $$
declare
  v_mode       text := case when p_rec ->> 'activeMode' in ('tourist', 'local') then p_rec ->> 'activeMode' end;
  v_trip       jsonb := economy_active_trip(p_rec);
  v_interests  text[];
  v_needs      text[];
  v_effort     text;
  v_teamed     boolean := economy_has_teamed_up(p_profile_id);
  v_picked     text[] := '{}';
  v_comp       integer := 0;
  v_solo       integer := 0;
  v_exclude    text[] := coalesce(p_exclude, '{}');
  v_recent     text[] := coalesce(p_recent, '{}');
  d            record;
begin
  if coalesce(p_n, 0) <= 0 then
    return v_picked;
  end if;
  v_interests := economy_text_array(p_rec #> '{universal,interests}')
                 || case when v_mode = 'tourist' then economy_text_array(v_trip -> 'interests') else '{}'::text[] end;
  v_needs := economy_text_array(p_rec #> '{universal,accessibility,needs}')
             || case when v_mode = 'tourist' then economy_text_array(v_trip #> '{accessibility,needs}') else '{}'::text[] end
             || economy_text_array(p_rec #> '{local,accessibility,needs}');
  v_effort := case p_rec #>> '{universal,exploration,pace}'
                when 'relaxed' then 'light' when 'balanced' then 'moderate' when 'fast' then 'big' end;
  select count(*) filter (where company = 'companion'), count(*) filter (where company is distinct from 'companion')
    into v_comp, v_solo
    from quest_defs where id = any (coalesce(p_existing, '{}'));

  for pass in 1..2 loop
    for d in
      select q.id, q.company
        from quest_defs q
       where q.category = p_category and not q.retired
         and q.id <> all (v_exclude) and q.id <> all (v_picked)
         and (pass = 2 or q.id <> all (v_recent))
         and (cardinality(q.modes) = 0 or v_mode = any (q.modes))
         and not (q.avoid_for && v_needs)
         and (p_category <> 'weekly' or q.company is distinct from 'companion' or v_teamed)
       order by
         case when p_category = 'adventure'
              then (select count(*) from unnest(q.interests) i where i = any (v_interests)) else 0 end desc,
         case when p_category = 'adventure' and v_effort is not null and q.effort = v_effort then 1 else 0 end desc,
         random()
    loop
      exit when cardinality(v_picked) >= p_n;
      if d.company = 'companion' then
        continue when v_comp >= 1;
        v_comp := v_comp + 1;
      else
        v_solo := v_solo + 1;
      end if;
      v_picked := v_picked || d.id;
    end loop;
    exit when cardinality(v_picked) >= p_n;
  end loop;

  if p_category <> 'weekly' and v_solo = 0 then
    v_picked := array(select x from unnest(v_picked) x
                       where x not in (select id from quest_defs where company = 'companion'));
  end if;
  return v_picked;
end;
$$;

-- Expires what's over and issues what's missing for the current periods. Call with the profile
-- locked. Returns the current keys: {"day":"d:…","week":"w:…","adventure":"a:…"}.
create or replace function economy_issue(p_profile_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_now    timestamptz := economy_now();
  v_tz     text;
  v_local  timestamp;
  v_rec    jsonb := economy_record(p_profile_id);
  v_day    text;
  v_week   text;
  v_adv    text;
  v_last   text;
  v_b      record;
  v_missing integer[];
  v_picked text[];
  i        integer;
begin
  select timezone into v_tz from profiles where id = p_profile_id;
  v_local := v_now at time zone v_tz;
  v_day  := 'd:' || to_char(v_local, 'YYYY-MM-DD');
  v_week := 'w:' || to_char(v_local, 'IYYY-"W"IW');
  v_adv  := 'a:' || to_char(v_local, 'IYYY-"W"IW');

  -- Periods only move forward (see the timezone note at the top of this file).
  select max(period_key) into v_last from quest_assignments where profile_id = p_profile_id and category = 'daily';
  if v_last > v_day then v_day := v_last; end if;
  select max(period_key) into v_last from quest_assignments where profile_id = p_profile_id and category = 'weekly';
  if v_last > v_week then v_week := v_last; end if;
  select max(period_key) into v_last from quest_assignments where profile_id = p_profile_id and category = 'adventure';
  if v_last > v_adv then v_adv := v_last; end if;

  update quest_assignments
     set status = 'expired'
   where profile_id = p_profile_id and status = 'active' and category <> 'starter'
     and (expires_at <= v_now
          or (category = 'daily' and period_key < v_day)
          or (category = 'weekly' and period_key < v_week)
          or (category = 'adventure' and period_key < v_adv));

  -- Weekly: one, not one used in the last 4 weeks.
  v_b := economy_period_bounds(v_week, v_tz);
  if v_b.ends_at > v_now
     and not exists (select 1 from quest_assignments where profile_id = p_profile_id and period_key = v_week and slot = 1) then
    v_picked := economy_pick(p_profile_id, v_rec, 'weekly', 1,
      array(select def_id from quest_assignments where profile_id = p_profile_id and period_key = v_week),
      array(select def_id from quest_assignments where profile_id = p_profile_id and category = 'weekly'
                                                   and assigned_at > v_now - interval '28 days'),
      '{}');
    if cardinality(v_picked) > 0 then
      perform economy_assign(p_profile_id, v_picked[1], 'weekly', v_week, 1, v_b.starts_at, v_b.ends_at);
    end if;
  end if;

  -- Dailies: three different ones, not yesterday's (= the previous day this person had dailies).
  v_b := economy_period_bounds(v_day, v_tz);
  v_missing := array(select s from generate_series(1, 3) s
                      where not exists (select 1 from quest_assignments
                                         where profile_id = p_profile_id and period_key = v_day and slot = s));
  if v_b.ends_at > v_now and cardinality(v_missing) > 0 then
    v_picked := economy_pick(p_profile_id, v_rec, 'daily', cardinality(v_missing),
      array(select def_id from quest_assignments where profile_id = p_profile_id and period_key = v_day),
      array(select def_id from quest_assignments
             where profile_id = p_profile_id and category = 'daily'
               and period_key = (select max(period_key) from quest_assignments
                                  where profile_id = p_profile_id and category = 'daily' and period_key < v_day)),
      array(select def_id from quest_assignments where profile_id = p_profile_id and period_key = v_day
                                                   and status in ('active', 'completed')));
    for i in 1..coalesce(cardinality(v_picked), 0) loop
      perform economy_assign(p_profile_id, v_picked[i], 'daily', v_day, v_missing[i], v_b.starts_at, v_b.ends_at);
    end loop;
  end if;

  -- Adventures: three personalised ones, none shown in the previous 3 weeks.
  v_b := economy_period_bounds(v_adv, v_tz);
  v_missing := array(select s from generate_series(1, 3) s
                      where not exists (select 1 from quest_assignments
                                         where profile_id = p_profile_id and period_key = v_adv and slot = s));
  if v_b.ends_at > v_now and cardinality(v_missing) > 0 then
    v_picked := economy_pick(p_profile_id, v_rec, 'adventure', cardinality(v_missing),
      array(select def_id from quest_assignments where profile_id = p_profile_id and period_key = v_adv),
      array(select def_id from quest_assignments where profile_id = p_profile_id and category = 'adventure'
                                                   and period_key <> v_adv and assigned_at > v_now - interval '21 days'),
      array(select def_id from quest_assignments where profile_id = p_profile_id and period_key = v_adv
                                                   and status in ('active', 'completed')));
    for i in 1..coalesce(cardinality(v_picked), 0) loop
      perform economy_assign(p_profile_id, v_picked[i], 'adventure', v_adv, v_missing[i], v_b.starts_at, v_b.ends_at);
    end loop;
  end if;

  -- Starter quests: every current one, once each, never expiring.
  perform economy_assign(p_profile_id, q.id, 'starter', 'starter', null, null, null)
     from quest_defs q
    where q.category = 'starter' and not q.retired
      and not exists (select 1 from quest_assignments a
                       where a.profile_id = p_profile_id and a.category = 'starter' and a.def_id = q.id);

  return jsonb_build_object('day', v_day, 'week', v_week, 'adventure', v_adv);
end;
$$;

create or replace function economy_ledger_json(l points_ledger) returns jsonb
language sql immutable as $$
  select jsonb_build_object('id', l.id, 'amount', l.amount, 'kind', l.kind, 'ref', l.ref,
                            'label', l.label, 'at', l.created_at)
$$;

-- One QuestAssignment (features/economy/types.ts).
create or replace function economy_assignment_json(a quest_assignments, p_rec jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  d       quest_defs;
  v_target integer;
  v_prog  integer := 0;
  v_paid  integer;
begin
  select * into d from quest_defs where id = a.def_id;
  v_target := economy_target(d.condition);
  if a.status = 'completed' then
    v_prog := v_target;
    select amount into v_paid from points_ledger where id = a.ledger_id;
  elsif a.status = 'active' then
    v_prog := least(v_target, greatest(0, economy_progress(a.profile_id, p_rec, d.condition, a.starts_at, a.expires_at, a.id)));
  end if;
  return jsonb_build_object(
    'id', a.id,
    'defId', a.def_id,
    'category', a.category,
    'periodKey', case when a.slot is not null and a.category <> 'weekly' then a.period_key || ':' || a.slot
                      else a.period_key end,
    'status', a.status,
    'progress', v_prog,
    'target', v_target,
    'claimable', a.status = 'active' and v_prog >= v_target and (a.expires_at is null or a.expires_at > economy_now()),
    'assignedAt', a.assigned_at,
    'expiresAt', a.expires_at,
    'completedAt', a.completed_at,
    'reward', coalesce(v_paid, d.reward));
end;
$$;

-- The whole EconomyState (features/economy/types.ts). p_keys = economy_issue()'s result.
create or replace function economy_build_state(p_profile_id uuid, p_keys jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_rec   jsonb := economy_record(p_profile_id);
  v_tz    text;
  v_bal   bigint;
  v_earn  bigint;
  v_spent bigint;
begin
  select timezone into v_tz from profiles where id = p_profile_id;
  select coalesce(sum(amount), 0), coalesce(sum(amount) filter (where amount > 0), 0),
         coalesce(-sum(amount) filter (where amount < 0), 0)
    into v_bal, v_earn, v_spent
    from points_ledger where profile_id = p_profile_id;

  return jsonb_build_object(
    'balance', v_bal,
    'earnedTotal', v_earn,
    'spentTotal', v_spent,
    'recent', coalesce((select jsonb_agg(economy_ledger_json(l) order by l.created_at desc, l.id)
                          from (select * from points_ledger where profile_id = p_profile_id
                                 order by created_at desc, id limit 50) l), '[]'::jsonb),
    'owned', coalesce((select jsonb_agg(item_id order by acquired_at, item_id)
                         from inventory where profile_id = p_profile_id), '[]'::jsonb),
    -- An item whose catalogue slot changed since it was equipped isn't reported in the old slot.
    'equipped', coalesce((select jsonb_object_agg(e.slot, e.item_id)
                            from equipped e left join shop_items s on s.id = e.item_id
                           where e.profile_id = p_profile_id and (s.id is null or s.slot = e.slot)), '{}'::jsonb),
    'quests', coalesce((select jsonb_agg(economy_assignment_json(a, v_rec)
                                         order by array_position(array['weekly', 'daily', 'adventure', 'starter'], a.category),
                                                  a.slot nulls last, a.assigned_at, a.def_id)
                          from quest_assignments a
                         where a.profile_id = p_profile_id
                           and (a.status = 'active'
                                or (a.status = 'completed'
                                    and (a.category = 'starter'
                                         or a.period_key in (p_keys ->> 'day', p_keys ->> 'week', p_keys ->> 'adventure'))))),
                       '[]'::jsonb),
    'history', coalesce((select jsonb_agg(economy_assignment_json(h, v_rec) order by h.completed_at desc, h.id)
                           from (select * from quest_assignments
                                  where profile_id = p_profile_id and status = 'completed'
                                  order by completed_at desc, id limit 50) h), '[]'::jsonb),
    'dailyRefreshAvailable',
      not exists (select 1 from daily_refreshes where profile_id = p_profile_id and period_key = p_keys ->> 'day')
      and exists (select 1 from quest_assignments where profile_id = p_profile_id and category = 'daily'
                                                    and period_key = p_keys ->> 'day' and status = 'active'),
    'nextDailyReset', (economy_period_bounds(p_keys ->> 'day', v_tz)).ends_at,
    'nextWeeklyReset', (economy_period_bounds(p_keys ->> 'week', v_tz)).ends_at,
    'timezone', v_tz,
    'source', 'server');
end;
$$;

-- record.rewards as old app versions expect it ({ledger, owned, equipped}, PointsEntry shape),
-- built from the tables. Read-only: migo_save_record ignores whatever the browser sends there.
-- Keeps the newest 200 entries; older ones are folded into two summary rows so the balance and the
-- earned total stay exact. Legacy entries keep their old refId, so old "claimed" checks still match.
create or replace function economy_rewards_mirror(p_profile_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_ledger jsonb;
  v_older_earned bigint;
  v_older_spent bigint;
begin
  with ranked as (
    select l.*, row_number() over (order by l.created_at desc, l.id desc) as rn
      from points_ledger l where l.profile_id = p_profile_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
             'id', r.id,
             'amount', r.amount,
             'reason', case when r.kind = 'purchase' or r.amount < 0 then 'purchase' else 'challenge' end,
             'refId', case when r.kind = 'legacy' then regexp_replace(substr(r.ref, 8), '#[0-9]+$', '')
                           when r.kind = 'purchase' then 'item:' || substr(r.ref, 10)
                           else r.ref end,
             'label', r.label,
             'at', floor(extract(epoch from r.created_at) * 1000)::bigint)
           order by r.created_at, r.id) filter (where r.rn <= 200), '[]'::jsonb),
         coalesce(sum(r.amount) filter (where r.rn > 200 and r.amount > 0), 0),
         coalesce(-sum(r.amount) filter (where r.rn > 200 and r.amount < 0), 0)
    into v_ledger, v_older_earned, v_older_spent
    from ranked r;

  if v_older_spent > 0 then
    v_ledger := jsonb_build_array(jsonb_build_object('id', 'mirror-spent', 'amount', -v_older_spent, 'reason', 'purchase',
                  'refId', 'mirror:spent', 'label', 'Earlier purchases', 'at', 0)) || v_ledger;
  end if;
  if v_older_earned > 0 then
    v_ledger := jsonb_build_array(jsonb_build_object('id', 'mirror-earned', 'amount', v_older_earned, 'reason', 'challenge',
                  'refId', 'mirror:earned', 'label', 'Earlier points', 'at', 0)) || v_ledger;
  end if;

  return jsonb_build_object(
    'ledger', v_ledger,
    'owned', coalesce((select jsonb_agg(item_id order by acquired_at, item_id) from inventory where profile_id = p_profile_id), '[]'::jsonb),
    'equipped', coalesce((select jsonb_object_agg(slot, item_id) from equipped where profile_id = p_profile_id), '{}'::jsonb));
end;
$$;

-- Refreshes the mirror in the saved record (only once the app has saved a record).
create or replace function economy_sync_mirror(p_profile_id uuid) returns void
language sql security definer set search_path = public as $$
  update migo_profiles
     set record = jsonb_set(record, '{rewards}', economy_rewards_mirror(p_profile_id), true)
   where profile_id = p_profile_id and record ? 'accountId';
$$;

-- Notes when the server first saw each pinned city in the record. p_trust_added_at (legacy import
-- only): use the record's addedAt (never later than now) instead of "now".
create or replace function economy_note_cities(p_profile_id uuid, p_rec jsonb, p_trust_added_at boolean default false)
returns void
language sql security definer set search_path = public as $$
  insert into seen_cities (profile_id, place_id, first_seen_at)
  select distinct on (btrim(c ->> 'placeId'))
         p_profile_id, btrim(c ->> 'placeId'),
         case when p_trust_added_at then least(coalesce(economy_ms(c -> 'addedAt'), economy_now()), economy_now())
              else economy_now() end
    from jsonb_array_elements(case when jsonb_typeof(p_rec #> '{universal,citiesDiscovered}') = 'array'
                                   then p_rec #> '{universal,citiesDiscovered}' else '[]'::jsonb end) c
   where jsonb_typeof(c) = 'object'
     and nullif(btrim(c ->> 'placeId'), '') is not null
     and char_length(c ->> 'placeId') <= 200
   order by btrim(c ->> 'placeId'), economy_ms(c -> 'addedAt') nulls last
  on conflict (profile_id, place_id) do nothing;
$$;

-- ---------------------------------------------------------------------------
-- Legacy import: record.rewards -> ledger, inventory, equipped (once per profile)
-- ---------------------------------------------------------------------------
-- Every old ledger entry becomes one 'legacy' row (ref 'legacy:<refId>', a '#2', '#3'… suffix if a
-- refId repeats) with its amount, label and time, so balances are identical. Owned ids become
-- inventory (price_paid from the old 'item:<id>' purchase entry, else 0), equipped stays equipped.
-- Profiles are marked in legacy_imports, so running this again never imports twice (and never
-- imports the read-only mirror that migo_save_record now writes). If an old ledger summed to less
-- than zero (only possible by tampering), an adjustment row brings it to zero.

create or replace function economy_import_legacy() returns integer
language plpgsql security definer set search_path = public as $$
declare
  m        record;
  v_rw     jsonb;
  v_ledger jsonb;
  v_owned  jsonb;
  v_eq     jsonb;
  v_sum    bigint;
  v_count  integer := 0;
begin
  for m in
    select mp.profile_id, mp.record, mp.updated_at
      from migo_profiles mp
     where not exists (select 1 from legacy_imports li where li.profile_id = mp.profile_id)
     order by mp.profile_id
       for update of mp
  loop
    perform 1 from profiles where id = m.profile_id for update;
    v_rw := case when jsonb_typeof(m.record -> 'rewards') = 'object' then m.record -> 'rewards' else '{}'::jsonb end;
    v_ledger := case when jsonb_typeof(v_rw -> 'ledger') = 'array' then v_rw -> 'ledger' else '[]'::jsonb end;
    v_owned := case when jsonb_typeof(v_rw -> 'owned') = 'array' then v_rw -> 'owned' else '[]'::jsonb end;
    v_eq := case when jsonb_typeof(v_rw -> 'equipped') = 'object' then v_rw -> 'equipped' else '{}'::jsonb end;

    with entries as (
      select x.e, x.ord,
             left(coalesce(nullif(btrim(x.e ->> 'refId'), ''), nullif(btrim(x.e ->> 'id'), ''), 'entry-' || x.ord), 200) as rid
        from jsonb_array_elements(v_ledger) with ordinality as x(e, ord)
       where jsonb_typeof(x.e) = 'object' and jsonb_typeof(x.e -> 'amount') = 'number'
         and abs((x.e ->> 'amount')::numeric) < 1000000000
         and round((x.e ->> 'amount')::numeric) <> 0
    ), numbered as (
      select e, ord, rid, row_number() over (partition by rid order by ord) as k from entries
    ), legacy_rows as (
      select m.profile_id as profile_id,
             round((e ->> 'amount')::numeric)::int as amount,
             'legacy'::text as kind,
             'legacy:' || rid || case when k > 1 then '#' || k else '' end as ref,
             left(coalesce(nullif(btrim(e ->> 'label'), ''),
                           case when (e ->> 'amount')::numeric < 0 then 'Shop purchase' else 'Challenge reward' end), 200) as label,
             coalesce(economy_ms(e -> 'at'), m.updated_at, economy_now()) as created_at
        from numbered
    )
    insert into points_ledger (profile_id, amount, kind, ref, label, created_at)
    select * from legacy_rows
    union all
    select m.profile_id, (-sum(amount))::int, 'adjustment', 'legacy:adjustment', 'Balance correction', economy_now()
      from legacy_rows having sum(amount) < 0
    on conflict (profile_id, ref) do nothing;

    insert into inventory (profile_id, item_id, price_paid, acquired_at)
    select m.profile_id, o.item_id, greatest(0, coalesce(-p.amount, 0)),
           coalesce(p.created_at, m.updated_at, economy_now())
      from (select distinct x #>> '{}' as item_id
              from jsonb_array_elements(v_owned) x
             where jsonb_typeof(x) = 'string' and char_length(x #>> '{}') between 1 and 100) o
      left join lateral (select l.amount, l.created_at from points_ledger l
                          where l.profile_id = m.profile_id and l.ref = 'legacy:item:' || o.item_id and l.amount < 0
                          limit 1) p on true
    on conflict (profile_id, item_id) do nothing;

    insert into equipped (profile_id, slot, item_id)
    select m.profile_id, j.key, j.value #>> '{}'
      from jsonb_each(v_eq) j
     where jsonb_typeof(j.value) = 'string'
       and j.key in ('head', 'hair', 'face', 'ears', 'neck', 'back', 'hand', 'backdrop')
       and exists (select 1 from inventory i where i.profile_id = m.profile_id and i.item_id = j.value #>> '{}')
    on conflict (profile_id, slot) do nothing;

    perform economy_note_cities(m.profile_id, m.record, true);

    select coalesce(sum(amount), 0) into v_sum from points_ledger where profile_id = m.profile_id;
    insert into legacy_imports (profile_id, imported_at, legacy_balance)
    values (m.profile_id, economy_now(), v_sum)
    on conflict (profile_id) do nothing;

    perform economy_sync_mirror(m.profile_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- API (called from frontend/src/lib/backend.ts; every write returns the fresh EconomyState)
-- ---------------------------------------------------------------------------
-- Errors: 42501 not your account; P0002 unknown profile/quest/item; 22023 bad input;
-- P0001 a rule said no, with a machine-readable HINT: not_finished, expired, completed, claimable,
-- refresh_used, none_available, insufficient_points, not_owned, timezone_rate_limited.

-- Everything the Quests page, Shop and points badge need. Issues the current period's quests
-- (lazily, on first call in a period) and marks old ones expired.
create or replace function economy_state(p_profile_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_keys jsonb;
begin
  perform economy_lock(p_profile_id);
  v_keys := economy_issue(p_profile_id);
  return economy_build_state(p_profile_id, v_keys);
end;
$$;

-- Pays a finished quest, once. Progress is recomputed here and the reward comes from quest_defs.
-- Calling it again for a paid quest just returns the state.
create or replace function economy_claim(p_profile_id uuid, p_assignment_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_keys jsonb;
  a      quest_assignments;
  d      quest_defs;
  v_lid  uuid;
  v_now  timestamptz := economy_now();
begin
  perform economy_lock(p_profile_id);
  v_keys := economy_issue(p_profile_id);
  select * into a from quest_assignments where id = p_assignment_id and profile_id = p_profile_id;
  if not found then
    raise exception 'Quest not found' using errcode = 'P0002';
  end if;
  if a.status = 'completed' then
    return economy_build_state(p_profile_id, v_keys);
  end if;
  if a.status <> 'active' or (a.expires_at is not null and a.expires_at <= v_now) then
    raise exception 'This quest has expired' using errcode = 'P0001', hint = 'expired';
  end if;
  select * into d from quest_defs where id = a.def_id;
  if economy_progress(p_profile_id, economy_record(p_profile_id), d.condition, a.starts_at, a.expires_at, a.id)
     < economy_target(d.condition) then
    raise exception 'Not finished yet' using errcode = 'P0001', hint = 'not_finished';
  end if;

  insert into points_ledger (profile_id, amount, kind, ref, label, created_at)
  values (p_profile_id, d.reward, 'quest', 'quest:' || a.id, left(d.title, 200), v_now)
  on conflict (profile_id, ref) do nothing
  returning id into v_lid;
  if v_lid is null then
    select id into v_lid from points_ledger where profile_id = p_profile_id and ref = 'quest:' || a.id;
  end if;
  update quest_assignments set status = 'completed', completed_at = v_now, ledger_id = v_lid where id = a.id;

  perform economy_sync_mirror(p_profile_id);
  return economy_build_state(p_profile_id, v_keys);
end;
$$;

-- Swaps one of today's unfinished dailies for a different one. Once a day; no points involved.
create or replace function economy_refresh_daily(p_profile_id uuid, p_assignment_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_keys   jsonb;
  a        quest_assignments;
  d        quest_defs;
  v_rec    jsonb;
  v_picked text[];
begin
  perform economy_lock(p_profile_id);
  v_keys := economy_issue(p_profile_id);
  v_rec := economy_record(p_profile_id);
  select * into a from quest_assignments where id = p_assignment_id and profile_id = p_profile_id;
  if not found then
    raise exception 'Quest not found' using errcode = 'P0002';
  end if;
  if a.category <> 'daily' then
    raise exception 'Only daily challenges can be refreshed' using errcode = '22023';
  end if;
  if a.status = 'completed' then
    raise exception 'This challenge is already completed' using errcode = 'P0001', hint = 'completed';
  end if;
  if a.status <> 'active' or a.period_key <> v_keys ->> 'day' then
    raise exception 'This challenge has expired' using errcode = 'P0001', hint = 'expired';
  end if;
  select * into d from quest_defs where id = a.def_id;
  if economy_progress(p_profile_id, v_rec, d.condition, a.starts_at, a.expires_at, a.id) >= economy_target(d.condition) then
    raise exception 'This challenge is done: claim it instead' using errcode = 'P0001', hint = 'claimable';
  end if;

  insert into daily_refreshes (profile_id, period_key, used_at)
  values (p_profile_id, a.period_key, economy_now())
  on conflict (profile_id, period_key) do nothing;
  if not found then
    raise exception 'Daily refresh already used' using errcode = 'P0001', hint = 'refresh_used';
  end if;

  v_picked := economy_pick(p_profile_id, v_rec, 'daily', 1,
    -- Not the one being replaced, nor anything else shown today.
    array(select def_id from quest_assignments where profile_id = p_profile_id and period_key = a.period_key),
    array(select def_id from quest_assignments
           where profile_id = p_profile_id and category = 'daily'
             and period_key = (select max(period_key) from quest_assignments
                                where profile_id = p_profile_id and category = 'daily' and period_key < a.period_key)),
    array(select def_id from quest_assignments where profile_id = p_profile_id and period_key = a.period_key
                                                 and status in ('active', 'completed') and id <> a.id));
  if cardinality(v_picked) = 0 then
    -- Raising rolls back the refresh row too, so it isn't used up.
    raise exception 'No other daily challenges to swap in' using errcode = 'P0001', hint = 'none_available';
  end if;

  update quest_assignments set status = 'replaced' where id = a.id;
  insert into quest_assignments (profile_id, def_id, category, period_key, slot, status, assigned_at, starts_at, expires_at)
  values (p_profile_id, v_picked[1], 'daily', a.period_key, a.slot, 'active', economy_now(), a.starts_at, a.expires_at);

  return economy_build_state(p_profile_id, v_keys);
end;
$$;

-- Buys an item at the server's price. Never equips it. Buying something already owned is a no-op.
create or replace function economy_purchase(p_profile_id uuid, p_item_id text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_keys jsonb;
  s      shop_items;
  v_bal  bigint;
  v_now  timestamptz := economy_now();
begin
  perform economy_lock(p_profile_id);
  v_keys := economy_issue(p_profile_id);
  select * into s from shop_items where id = p_item_id;
  if not found then
    raise exception 'Unknown item %', p_item_id using errcode = 'P0002';
  end if;
  if exists (select 1 from inventory where profile_id = p_profile_id and item_id = s.id) then
    return economy_build_state(p_profile_id, v_keys);
  end if;
  if s.retired then
    raise exception 'This item is no longer sold' using errcode = '22023';
  end if;
  select coalesce(sum(amount), 0) into v_bal from points_ledger where profile_id = p_profile_id;
  if v_bal < s.price then
    raise exception 'Not enough points' using errcode = 'P0001', hint = 'insufficient_points';
  end if;

  insert into points_ledger (profile_id, amount, kind, ref, label, created_at)
  values (p_profile_id, -s.price, 'purchase', 'purchase:' || s.id, left('Bought ' || coalesce(nullif(s.name, ''), s.id), 200), v_now);
  insert into inventory (profile_id, item_id, price_paid, acquired_at) values (p_profile_id, s.id, s.price, v_now);

  perform economy_sync_mirror(p_profile_id);
  return economy_build_state(p_profile_id, v_keys);
end;
$$;

-- Puts an owned item in its slot (replacing what was there), or empties the slot (p_item_id null).
create or replace function economy_equip(p_profile_id uuid, p_slot text, p_item_id text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_keys jsonb;
  s      shop_items;
begin
  perform economy_lock(p_profile_id);
  if p_slot is null or p_slot not in ('head', 'hair', 'face', 'ears', 'neck', 'back', 'hand', 'backdrop') then
    raise exception 'Unknown slot %', p_slot using errcode = '22023';
  end if;
  if p_item_id is null then
    delete from equipped where profile_id = p_profile_id and slot = p_slot;
  else
    if not exists (select 1 from inventory where profile_id = p_profile_id and item_id = p_item_id) then
      raise exception 'You don''t own this item' using errcode = 'P0001', hint = 'not_owned';
    end if;
    select * into s from shop_items where id = p_item_id;
    if not found then
      raise exception 'Unknown item %', p_item_id using errcode = 'P0002';
    end if;
    if s.slot <> p_slot then
      raise exception 'That item goes in the % slot', s.slot using errcode = '22023';
    end if;
    insert into equipped (profile_id, slot, item_id) values (p_profile_id, p_slot, p_item_id)
    on conflict (profile_id, slot) do update set item_id = excluded.item_id;
  end if;
  v_keys := economy_issue(p_profile_id);
  perform economy_sync_mirror(p_profile_id);
  return economy_build_state(p_profile_id, v_keys);
end;
$$;

-- Records that the person opened a section of the app (for "visit" quests).
create or replace function economy_record_visit(p_profile_id uuid, p_page text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_page is null or p_page not in ('map', 'shop', 'gallery', 'chat', 'quests') then
    raise exception 'Unknown page %', p_page using errcode = '22023';
  end if;
  perform economy_lock(p_profile_id);
  insert into app_visits (profile_id, page, first_at, last_at)
  values (p_profile_id, p_page, economy_now(), economy_now())
  on conflict (profile_id, page) do update set last_at = greatest(app_visits.last_at, excluded.last_at);
end;
$$;

-- Saves the person's IANA timezone. The first change is always allowed, then at most one change
-- every 20 hours. Active quests' windows move to the new timezone (see the note at the top).
create or replace function economy_set_timezone(p_profile_id uuid, p_tz text) returns void
language plpgsql security definer set search_path = public as $$
declare
  p     profiles;
  v_now timestamptz := economy_now();
  a     record;
  v_b   record;
begin
  p := economy_lock(p_profile_id);
  if p_tz is null or not exists (select 1 from pg_timezone_names where name = p_tz) then
    raise exception 'Unknown timezone %', p_tz using errcode = '22023';
  end if;
  if p.timezone = p_tz then
    return;
  end if;
  if p.timezone_changed_at is not null and p.timezone_changed_at > v_now - interval '20 hours' then
    raise exception 'The timezone can only change once every 20 hours' using errcode = 'P0001', hint = 'timezone_rate_limited';
  end if;
  update profiles set timezone = p_tz, timezone_changed_at = v_now where id = p_profile_id;
  for a in select id, period_key from quest_assignments
            where profile_id = p_profile_id and status = 'active' and category <> 'starter' loop
    v_b := economy_period_bounds(a.period_key, p_tz);
    update quest_assignments set starts_at = v_b.starts_at, expires_at = v_b.ends_at where id = a.id;
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- migo_save_record: same signature and rules as 005, but record.rewards is now server-owned
-- ---------------------------------------------------------------------------

create or replace function migo_save_record(p_profile_id uuid, p_record jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare
  mode text := p_record ->> 'activeMode';
  rec  jsonb;
begin
  perform migo_assert_owner(p_profile_id);
  if jsonb_typeof(p_record) is distinct from 'object' then
    raise exception 'Record must be a JSON object' using errcode = '22023';
  end if;
  if (p_record ->> 'accountId') is distinct from p_profile_id::text then
    raise exception 'Record belongs to a different account' using errcode = '22023';
  end if;
  perform 1 from profiles where id = p_profile_id for update;
  if not found then
    raise exception 'Unknown profile %', p_profile_id using errcode = 'P0002';
  end if;

  -- Points and items the browser sends are ignored: only economy_* functions change them.
  -- (Marking the profile as imported means a re-run of the legacy import never reads this mirror.)
  insert into legacy_imports (profile_id, imported_at, legacy_balance)
  values (p_profile_id, economy_now(), 0)
  on conflict (profile_id) do nothing;
  rec := jsonb_set(p_record, '{rewards}', economy_rewards_mirror(p_profile_id), true);

  insert into migo_profiles (profile_id, record, updated_at)
  values (p_profile_id, rec, now())
  on conflict (profile_id) do update set record = excluded.record, updated_at = now();

  perform economy_note_cities(p_profile_id, rec, false);

  update profiles
     set role    = case when mode in ('tourist', 'local') then mode end,
         has_dog = coalesce(p_record #>> '{universal,dogs,stance}', '') = 'has-dog'
   where id = p_profile_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Carry over existing points (idempotent: only profiles not imported yet)
-- ---------------------------------------------------------------------------

select economy_import_legacy() as profiles_imported;

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------
-- Supabase grants new functions to anon/authenticated by default, so revoke from them explicitly.

revoke execute on function economy_now() from public, anon, authenticated;
revoke execute on function economy_text_array(jsonb) from public, anon, authenticated;
revoke execute on function economy_ms(jsonb) from public, anon, authenticated;
revoke execute on function economy_ledger_not_negative() from public, anon, authenticated;
revoke execute on function economy_ledger_immutable() from public, anon, authenticated;
revoke execute on function economy_lock(uuid) from public, anon, authenticated;
revoke execute on function economy_record(uuid) from public, anon, authenticated;
revoke execute on function economy_active_trip(jsonb) from public, anon, authenticated;
revoke execute on function economy_period_bounds(text, text) from public, anon, authenticated;
revoke execute on function economy_target(jsonb) from public, anon, authenticated;
revoke execute on function economy_has_teamed_up(uuid) from public, anon, authenticated;
revoke execute on function economy_progress(uuid, jsonb, jsonb, timestamptz, timestamptz, uuid) from public, anon, authenticated;
revoke execute on function economy_legacy_ref(text, text, text) from public, anon, authenticated;
revoke execute on function economy_assign(uuid, text, text, text, integer, timestamptz, timestamptz) from public, anon, authenticated;
revoke execute on function economy_pick(uuid, jsonb, text, integer, text[], text[], text[]) from public, anon, authenticated;
revoke execute on function economy_issue(uuid) from public, anon, authenticated;
revoke execute on function economy_ledger_json(points_ledger) from public, anon, authenticated;
revoke execute on function economy_assignment_json(quest_assignments, jsonb) from public, anon, authenticated;
revoke execute on function economy_build_state(uuid, jsonb) from public, anon, authenticated;
revoke execute on function economy_rewards_mirror(uuid) from public, anon, authenticated;
revoke execute on function economy_sync_mirror(uuid) from public, anon, authenticated;
revoke execute on function economy_note_cities(uuid, jsonb, boolean) from public, anon, authenticated;
revoke execute on function economy_import_legacy() from public, anon, authenticated;

revoke execute on function economy_state(uuid) from public, anon, authenticated;
revoke execute on function economy_claim(uuid, uuid) from public, anon, authenticated;
revoke execute on function economy_refresh_daily(uuid, uuid) from public, anon, authenticated;
revoke execute on function economy_purchase(uuid, text) from public, anon, authenticated;
revoke execute on function economy_equip(uuid, text, text) from public, anon, authenticated;
revoke execute on function economy_record_visit(uuid, text) from public, anon, authenticated;
revoke execute on function economy_set_timezone(uuid, text) from public, anon, authenticated;
revoke execute on function migo_save_record(uuid, jsonb) from public;
-- anon too: device accounts without a login use the same owner rule as the migo_* functions.
grant execute on function economy_state(uuid) to anon, authenticated;
grant execute on function economy_claim(uuid, uuid) to anon, authenticated;
grant execute on function economy_refresh_daily(uuid, uuid) to anon, authenticated;
grant execute on function economy_purchase(uuid, text) to anon, authenticated;
grant execute on function economy_equip(uuid, text, text) to anon, authenticated;
grant execute on function economy_record_visit(uuid, text) to anon, authenticated;
grant execute on function economy_set_timezone(uuid, text) to anon, authenticated;
grant execute on function migo_save_record(uuid, jsonb) to anon, authenticated;
